const includeWords =
  /\b(appointed|promoted|promotion|named as|joins|joined|elected|selected as|takes over as|assumes role|wins|won|awarded|honored|honoured|recognized|recognised|achievement|milestone)\b/i;

const excludeWords =
  /\b(meeting|engages|visit|war|attack|politics|minister|navy|army|cricket|football|match|arrested|dies|death)\b/i;

return items.filter((item) => {
  const title = item.json.title || '';
  const description = item.json.contentSnippet || '';
  const text = `${title} ${description}`;

  return includeWords.test(text) && !excludeWords.test(text);

});

