const responses = $input.all();
const sourceItems = $("Code in JavaScript5").all();

return responses.map((item, index) => {
  const sourceData = sourceItems[index]?.json ?? {};
  const rawResponse = String(item.json.data ?? "");

  let originalArticleUrl = "";

  try {
    // Google response ke start se security prefix remove karta hai
    const cleanResponse = rawResponse.replace(/^\)\]\}'\s*/, "").trim();

    // Outer Google response parse karo
    const outerData = JSON.parse(cleanResponse);

    // Is field ke andar ek aur JSON string hoti hai
    const innerResponse = outerData?.[0]?.[2];

    if (typeof innerResponse === "string") {
      const decodedResponse = JSON.parse(innerResponse);

      if (
        decodedResponse?.[0] === "garturlres" &&
        typeof decodedResponse?.[1] === "string"
      ) {
        originalArticleUrl = decodedResponse[1];
      }
    }
  } catch (error) {
    // Decode fail hone par workflow ko stop nahi karega
  }

  return {
    json: {
      ...sourceData,
      original_article_url: originalArticleUrl,
      decode_status: originalArticleUrl ? "SUCCESS" : "FAILED",
    },
    pairedItem: {
      item: index,
    },
  };
});

const imageItems = $input.all();
const sourceItems = $("If").all();

return imageItems.map((item, index) => {
  const sourceData = sourceItems[index]?.json ?? {};

  const articleImage = item.json.article_image_url || "";
  const fallbackImage = item.json.fallback_image_url || "";
  const finalImage = articleImage || fallbackImage;

  return {
    json: {
      ...sourceData,
      article_image_url: articleImage,
      fallback_image_url: fallbackImage,
      profile_image_url: finalImage,
      image_status: finalImage ? "FOUND" : "MISSING",
    },
    pairedItem: {
      item: index,
    },
  };
});

const items = $input.all();

return items.map((item, index) => {
  const sourceUrl = item.json["Source URL"];

  if (!sourceUrl) {
    throw new Error(`Item ${index + 1}: Source URL missing hai`);
  }

  const match = sourceUrl.match(/\/articles\/([^?]+)/);

  if (!match) {
    throw new Error(`Item ${index + 1}: Google News article ID nahi mila`);
  }

  return {
    json: {
      ...item.json,
      google_news_url: sourceUrl,
      google_news_id: match[1],
    },
    pairedItem: {
      item: index,
    },
  };
});

const htmlItems = $input.all();
const sourceItems = $("Code in JavaScript4").all();

return htmlItems.map((item, index) => {
  const sourceData = sourceItems[index]?.json ?? {};

  const signature = item.json.signature;
  const timestamp = item.json.timestamp;
  const articleId = sourceData.google_news_id;

  if (!signature || !timestamp || !articleId) {
    throw new Error(
      `Item ${index + 1}: signature, timestamp ya Google News ID missing hai`
    );
  }

  const requestPayload = [
    "Fbv4je",
    JSON.stringify([
      "garturlreq",
      [
        [
          "X",
          "X",
          ["X", "X"],
          null,
          null,
          1,
          1,
          "US:en",
          null,
          1,
          null,
          null,
          null,
          null,
          null,
          0,
          1
        ],
        "X",
        "X",
        1,
        [1, 1, 1],
        1,
        1,
        null,
        0,
        0,
        null,
        0
      ],
      articleId,
      Number(timestamp),
      signature
    ])
  ];

  return {
    json: {
      ...sourceData,
      signature,
      timestamp,
      f_req: JSON.stringify([[requestPayload]])
    },
    pairedItem: {
      item: index
    }
  };
});

